    inv = re.compile(r"^[ \t]*" + re.escape(name) + r"[ \t]+\"" + re.escape(label) + r"\"")
    inv_at = [i + 1 for i, ln in enumerate(lines) if inv.match(ln)]

    if kind == "EXTERNAL":
