CASE_CLOSE = "esac"
LABEL_ROW = re.compile(r"^\s{2}([a-z0-9|*-]+)\)\s*(.*)$")
try:
    a = next(i for i, l in enumerate(lines) if l.startswith(CASE_OPEN))
    b = next(i for i in range(a, len(lines)) if lines[i] == CASE_CLOSE)
