                     % "|".join(HELPERS))
LABEL_ARG = re.compile(r'^"((?:[^"\\]|\\.)*)"\s*(.*)$')
found = []
for i, ln in enumerate(lines):
    if not uncomment(ln):
        continue
    m = CALLPOS.search(ln)
