SPEC = re.compile(r"%[-#0 +]*[0-9]*(?:\.[0-9]+)?[sdiroxefgu]")
DIGITS = re.compile(r"[0-9]+")
PRINT_OPEN = re.compile(r"^[ \t]*print\(")
ECHO_LINE = re.compile(r'^[ \t]*echo[ \t]+"(.*)"[ \t]*$')
