  if [ "$rc" -ne 0 ]; then echo "         The theorem permits d=5 (CIRCULAR_KING_WEN.md witness); say 'within the canonical' or name d=5."; return 1; fi
  echo "  [ok] GATE 68: $pn wrap-distance enumeration(s) in $F, each scoped or naming d=5"
